function workerColor(issueId: IssueId | undefined): string | undefined {
  if (issueId === undefined) return "gray";
  const numericId = typeof issueId === "number"
    ? issueId
    : Array.from(issueId).reduce((sum, ch) => sum + ch.charCodeAt(0), 0);
  return workerColors[numericId % workerColors.length];
}

function renderLogLine(entry: IndexedRunLogEntry): string {
  const issuePrefix = entry.issueId === undefined ? "[run]" : `[#${String(entry.issueId)}]`;
  const phaseSuffix = entry.phase === undefined ? "" : ` ${entry.phase}`;
  return `${issuePrefix}${phaseSuffix} ${entry.text}`;
}

function renderRunUsageLines(state: InkRunViewState): string[] {
  const lines = [
    `input ${formatTokenCount(state.runUsage.inputTokens)}`,
    `output ${formatTokenCount(state.runUsage.outputTokens)}`,
    `total ${state.runUsage.hasUnknownTokens ? "unknown" : formatTokenCount(state.runUsage.totalTokens)}`,
    `cost ${formatUsageCost(state.runUsage)}`,
  ];

  if (!hasInProgressUsage(state)) {
    lines.push("in-progress usage none");
    return lines;
  }

  const inProgress = displayRunUsage(state);
  lines.push(
    `in-progress usage input ${formatTokenCount(inProgress.inputTokens)} · output ${formatTokenCount(inProgress.outputTokens)} · total ${inProgress.hasUnknownTokens ? "unknown" : formatTokenCount(inProgress.totalTokens)} · cost ${formatUsageCost(inProgress)}`,
  );
  return lines;
}

